from pathlib import Path
import json,html
base=Path(__file__).resolve().parent
records=json.loads((base/'atlas_seed_catalog.json').read_text())['items']
styles='''<style>
:root{color-scheme:dark;--bg:#090a0a;--gold:#c7a66c;--paper:#f4efe6;--muted:#bab3a7;--line:#484238}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--paper);font:16px/1.6 system-ui,sans-serif}button,input{font:inherit}button{cursor:pointer}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:4px}.frame{max-width:1460px;width:calc(100% - clamp(38px,7vw,130px));margin:auto}.top{padding:23px 0;display:flex;align-items:center;gap:20px;justify-content:space-between;border-bottom:1px solid #655844}.brand{text-decoration:none;font-weight:800;letter-spacing:.16em;font-size:13px}.kicker{font:11px ui-monospace,monospace;letter-spacing:.15em;text-transform:uppercase;color:var(--gold)}h1,h2,h3{font-family:Fraunces,Georgia,serif;font-weight:400}h1{font-size:clamp(64px,8vw,125px);line-height:.92;letter-spacing:-.06em;margin:23px 0}h1 em{color:var(--gold);font-weight:400}h2{font-size:clamp(30px,3vw,48px);line-height:1.1}p{color:var(--muted)}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:5vw;align-items:center;padding:100px 0 90px}.lead{max-width:650px;font-size:clamp(18px,2vw,24px);line-height:1.6}.scope{display:flex;gap:14px;align-items:center;margin-top:40px}.scope i{background:var(--gold);width:6px;height:6px;border-radius:50%}.scope span{font:11px ui-monospace,monospace;color:var(--gold)}.field{min-height:430px;position:relative;isolation:isolate;border:1px solid #554938;background:radial-gradient(ellipse at center,#323022,#141613 43%,#0b0d0b 70%);overflow:hidden;display:grid;place-items:center}.field:before{content:"";position:absolute;inset:0;background-image:linear-gradient(#c5a86c16 1px,transparent 1px),linear-gradient(90deg,#c5a86c16 1px,transparent 1px);background-size:38px 38px}.ring{position:absolute;width:60%;aspect-ratio:1;border:1px solid #c7a66c77;border-radius:50%}.ring:nth-child(2){width:37%;border-style:dashed}.ring:nth-child(3){width:18%}.field__caption{position:absolute;bottom:19px;left:19px;right:19px;font:11px ui-monospace,monospace;color:#d4c6a5;z-index:2}.field__label{z-index:2;text-align:center;font:11px ui-monospace,monospace;color:var(--gold);letter-spacing:.14em}.field__label b{display:block;font:400 58px Fraunces,Georgia,serif;color:var(--paper);margin-bottom:10px}.browse{border-top:1px solid var(--line);padding:78px 0}.browse__top{display:flex;justify-content:space-between;gap:30px;align-items:end}.browse__top p{max-width:370px}.filters{display:flex;flex-wrap:wrap;gap:9px;margin:30px 0 32px}.filters button{background:#171816;border:1px solid #6b5e49;color:var(--paper);font:11px ui-monospace,monospace;padding:12px 14px}.filters button[aria-pressed="true"]{background:var(--gold);border-color:var(--gold);color:#15130e}.searchbar{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 0 30px;border-top:1px solid var(--line)}.searchbar label{font:11px ui-monospace,monospace;color:var(--gold);white-space:nowrap}.searchbar input{width:min(520px,100%);padding:13px 15px;border:1px solid #76674d;background:#171816;color:var(--paper)}.status{font:11px ui-monospace,monospace;color:var(--gold);min-width:90px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:17px}.case{min-width:0;border:1px solid var(--line);background:linear-gradient(150deg,#1b1b18,#10110f);padding:24px;min-height:290px;display:flex;flex-direction:column;justify-content:space-between}[hidden]{display:none!important}.case[hidden]{display:none}.case__number{display:flex;justify-content:space-between;gap:8px;font:10px ui-monospace,monospace;color:var(--gold)}.case h3{font-size:clamp(27px,2.6vw,39px);line-height:1.1;margin:22px 0 8px}.case p{font-size:14px;margin:0 0 20px}.case a{display:inline-flex;align-items:center;text-decoration:none;border-bottom:1px solid var(--gold);color:var(--paper);padding:10px 0;font-size:12px;align-self:flex-start}.note{border-left:2px solid var(--gold);padding-left:24px;margin-top:48px;color:var(--muted);max-width:910px}.note b{color:var(--paper)}.footer{padding:50px 0 65px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:30px;font-size:13px}.footer a{color:var(--gold)}@media(max-width:950px){.hero{grid-template-columns:1fr}.field{min-height:320px}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.hero{padding:60px 0}.field{min-height:270px}.field__label b{font-size:44px}.cards{grid-template-columns:1fr}.browse__top,.searchbar{display:block}.searchbar input{display:block;margin-top:10px}.status{display:block;margin-top:10px}.footer{display:block}}@media(prefers-reduced-motion:reduce){*,*:after,*:before{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style>'''
fields=[]
for i,r in enumerate(records):
 fields.append(f'''<article class="case" data-theme="{html.escape(r['theme'],quote=True)}" data-search="{html.escape((r['title']+' '+r['theme']+' '+r['place_candidate']).lower(),quote=True)}"><div><div class="case__number"><span>RECORD {i+1:02d}</span><span>{html.escape(r['theme'])}</span></div><h3>{html.escape(r['title'])}</h3><p>{html.escape(r['place_candidate'])} · Research location pending confirmation</p></div><a href="{html.escape(r['url'],quote=True)}" target="_blank" rel="noopener noreferrer">Read published investigation ↗</a></article>''')
themes=sorted({r['theme'] for r in records})
filter_buttons='<button type="button" data-filter="all" aria-pressed="true">All records</button>'+''.join(f'<button type="button" data-filter="{html.escape(t,quote=True)}" aria-pressed="false">{html.escape(t)}</button>' for t in themes)
script='''<script>(()=>{'use strict';const controls=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.case')],search=document.getElementById('search');if(!controls.length||!cards.length||!search)return;let active='all';function apply(){let count=0;const term=search.value.trim().toLowerCase();cards.forEach(card=>{const match=(active==='all'||card.dataset.theme===active)&&(!term||card.dataset.search.includes(term));card.hidden=!match;if(match)count++});document.getElementById('status').textContent=`${count} of ${cards.length} published investigations shown`;}controls.forEach(btn=>btn.addEventListener('click',()=>{active=btn.dataset.filter;controls.forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));apply()}));search.addEventListener('input',apply);document.querySelectorAll('[data-enhancement]').forEach(el=>el.hidden=false);apply();})();</script>'''
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evidence Atlas — Source Review Preview | Final Vestige</title><meta name="description" content="A research queue of real Final Vestige investigations, intentionally not mapped until locations are verified.">'''+styles+'''</head><body><header class="top frame"><a href="https://finalvestige.com/" class="brand">FINAL VESTIGE STUDIOS</a><span class="kicker">EVIDENCE ATLAS / RESEARCH PREVIEW</span></header><main><div class="hero frame"><div><span class="kicker">A MAP OF WHAT CAN BE PROVEN</span><h1>Every story <em>begins somewhere.</em></h1><p class="lead">Our archive moves across centuries and continents. Before we put a marker on a map, we follow each story back to its original record—and confirm exactly what that location means.</p><div class="scope"><i></i><span>6 VERIFIED PUBLISHED ARTICLES · 0 APPROVED MAP PINS</span></div></div><div class="field" role="img" aria-label="Decorative concentric circles. This is not a geographic map; no story locations have been plotted."><span class="ring"></span><span class="ring"></span><span class="ring"></span><div class="field__label"><b>00</b> VERIFIED LOCATION PINS</div><div class="field__caption">DATA REVIEW IN PROGRESS<br>NO SPECULATIVE COORDINATES</div></div></div><section class="browse"><div class="frame"><div class="browse__top"><div><span class="kicker">THE OPEN CATALOG</span><h2>Start with the record.</h2></div><p>These six articles exist on Final Vestige today. Each is awaiting separate location-specific source validation before geographic mapping.</p></div><div class="filters" data-enhancement hidden aria-label="Filter investigation theme">'''+filter_buttons+'''</div><div class="searchbar" data-enhancement hidden><label for="search">SEARCH ARTICLES</label><input id="search" type="search" placeholder="Title, subject, or candidate place" aria-controls="cases"><span class="status" id="status" role="status" aria-live="polite">6 published investigations</span></div><div class="cards" id="cases">'''+''.join(fields)+'''</div><div class="note"><b>Why no pins?</b> A photograph's location, an event's location and a document's discovery site can be different. The map appears only when primary sources and precision have been checked. This graphic is an abstract design study, not a factual map.</div></div></section></main><footer class="footer frame"><span>FINAL VESTIGE / THE LIVING ARCHIVE — RESEARCH PREVIEW</span><a href="https://finalvestige.com/">Return to Final Vestige ↗</a></footer>'''+script+'''</body></html>'''
(base/'atlas-preview.html').write_text(page,encoding='utf-8')
print('Wrote Atlas preview',len(page))
